// MixedModelSaturation proves the bound laws can fail: per law, a
// defect is worn on each method the law's closures reach — zeros, the
// fixture pair alternated, a waning count — and at least one worn run must
// fail naming the law's own identifier, with the clean factory standing as
// reference. A law every defect survives is bound but unsaturatable, and
// fails here by name. Pass the same options that arm the tier: a law behind
// an unarmed door or the clocked factory is skipped visibly, never counted.
func MixedModelSaturation(t *testing.T, factory func() ttl.Mixed, opts ...MixedModelOption) {
	t.Helper()
	cfg := newMixedModelConfig(opts...)
	_ = cfg
	fx := DefaultMixedFixture()
	_ = fx
	t.Run("AUTO-WRITE-OBSERVABLE", func(t *testing.T) {
		killed := func() bool {
			for _, method := range []string{"Put", "Read"} {
				for _, wear := range mixedSatWears[method] {
					// Two references per defect. Silencing the differential leaves
					// the law as the only witness, but not every action reports
					// through it: a shape whose action fails structurally still
					// ends the iteration, and a reference wearing the same defect
					// behaves the same way the subject does, so nothing diverges
					// and the law is reached. A law that *is* the comparison needs
					// the opposite — with both sides worn it has nothing to
					// disagree with — so the clean reference runs too and either
					// kill counts. The corpus measured both: dropping either one
					// loses laws that only the other can saturate.
					for _, blind := range []bool{true, false} {
						surrogate := "MixedSat_AUTO-WRITE-OBSERVABLE_" + method + "_" + wear.kind
						if blind {
							surrogate += "_blind"
						}
						t.Cleanup(func() {
							_ = os.RemoveAll(filepath.Join("testdata", "rapid", surrogate))
							_ = os.Remove(filepath.Join(
								model.ResolveArtifactDir(""), "failure-"+surrogate+".json"))
						})
						reference := factory
						if blind {
							reference = func() ttl.Mixed { return wear.wrap(fx, factory()) }
						}
						f := testkit.NewFailableTB().WithName(surrogate)
						worn := append(slices.Clone(opts),
							MixedModelReference(reference),
							mixedModelOnlyLaw("AUTO-WRITE-OBSERVABLE"))
						model.Check(f, MixedModelProperty(func() ttl.Mixed {
							return wear.wrap(fx, factory())
						}, worn...))
						// The reporter's own rendering, not the bare identifier.
						// rapid echoes the TB's name into its final message and the
						// surrogate above is named for this law, so matching the
						// identifier alone matched the name — the criterion reduced
						// to f.Failed() and every defect "killed" every law. The
						// verdict's format carries the identifier where no name can:
						// after the kind, which is the one place only the reporter
						// writes. The suffix rather than the whole prefix because a
						// REQ-tagged law renders "[REQ-1 invariant]".
						if f.Failed() && (strings.Contains(f.Msg(), "invariant] AUTO-WRITE-OBSERVABLE")) {
							return true
						}
					}
				}
			}
			return false
		}()
		if !killed {
			t.Errorf("AUTO-WRITE-OBSERVABLE survived every defect worn on its own methods — bound but unsaturatable")
		}
	})
	t.Run("AUTO-TTL-EXPIRY", func(t *testing.T) {
		t.Skip("a clocked law's factory builds its own subjects on the run's clock; a worn defect never reaches it")
	})
}

